localStorage.setItem("placar", "12");
const placar = Number(localStorage.getItem("placar"));
// placar vale 12 (número), porque Number converte o texto.

const aluno = { nome: "Caio", serie: 9 };
localStorage.setItem("aluno", JSON.stringify(aluno));
const lido = JSON.parse(localStorage.getItem("aluno"));
console.log(lido.nome); // Caio
